questions.questionTextEn:
Consider the C code:
```c
int x = 5, y = 10;
if (x > 10 && ++y > 10)
    x = 20;
printf("%d %d", x, y);
```
What is the output?

What integer is printed by the following C program?
```c
#include <stdio.h>
int g(int n) {
    if (n == 0) return 0;
    return (n % 10) + g(n / 10);
}
int main() {
    printf("%d", g(4729));
    return 0;
}
```

On a system where `char` is 1 byte (1-byte aligned), `short` is 2 bytes (2-byte aligned), and `int` is 4 bytes (4-byte aligned), what are `sizeof(struct A)` and `sizeof(struct B)`?
```c
struct A { char c1; int x; char c2; };
struct B { int x; char c1; char c2; };
```

What is printed by the following C program?
```c
#include <stdio.h>
void p(int n) {
    if (n <= 0) return;
    p(n - 1);
    printf("%d ", n);
    p(n - 2);
}
int main() { p(3); return 0; }
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int len(char *s) {
    if (*s == '\0') return 0;
    return 1 + len(s + 1);
}
int main() {
    char str[] = "DATA\0STRUCT";
    printf("%d", len(str));
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    int n = 45, ans = 0;
    while (n > 0) {
        ans = (ans << 1) | (n & 1);
        n >>= 1;
    }
    printf("%d", ans);
    return 0;
}
```

What is the output of the following C program?
```c
#include <stdio.h>
void swap_ptr(int **a, int **b) {
    int *t = *a;
    *a = *b;
    *b = t;
}
int main() {
    int x = 10, y = 20;
    int *p = &x, *q = &y;
    swap_ptr(&p, &q);
    printf("%d %d %d %d", x, y, *p, *q);
    return 0;
}
```
